UPDATE email_fragments SET fragment = '<tr><td style="background-color: #f5f5f5; padding: 24px; text-align: center; font-family: Arial, Helvetica, sans-serif; font-size: 12px; color: #777777;"><p style="margin: 0;">© 2026 LMT</p><p style="margin: 8px 0 0 0;">Ta wiadomość została wygenerowana automatycznie. Prosimy na nią nie odpowiadać.</p><p style="margin: 8px 0 0 0;">W razie pytań skontaktuj się z nami:<a href="mailto:${contactEmail}" style="color: #777777;">${contactEmail}</a>lub telefonicznie pod numerem<a href="tel:${contactNumber}" style="color: #777777;">${contactNumber}</a>.</p></td></tr>' WHERE name = 'Reservation Created Organization pl';
UPDATE email_fragments SET fragment = '<tr><td style="background-color: #f5f5f5; padding: 24px; text-align: center; font-family: Arial, Helvetica, sans-serif; font-size: 12px; color: #777777;"><p style="margin: 0;">© 2026 LMT</p><p style="margin: 8px 0 0 0;">This message was generated automatically. Please do not reply to it.</p><p style="margin: 8px 0 0 0;">If you have any questions, please contact us at<a href="mailto:${contactEmail}" style="color: #777777;">${contactEmail}</a>or call us at<a href="tel:${contactNumber}" style="color: #777777;">${contactNumber}</a>.</p></td></tr>' WHERE name = 'Reservation Created Organization en';

UPDATE email_fragments SET fragment = '<tr> <td style="background-color: #ffffff; padding: 40px; font-family: Arial, Helvetica, sans-serif; color: #333333;"> <h1 style=" margin-top: 0; text-align: center;"> ${nick} witaj w VipSound! </h1> <p> Na razie Twoje konto nie jest jeszcze aktywne. Użyj linku poniżej aby je aktywować i rezerwować sale </p> <a href="${link}"> AKTYWUJ KONTO </a> </td> </tr>' WHERE name = 'Activation Code pl';
UPDATE email_fragments SET fragment = '<tr> <td style="background-color: #ffffff; padding: 40px; font-family: Arial, Helvetica, sans-serif; color: #333333;"> <h1 style="margin-top: 0; text-align: center;"> Welcome to VipSound, ${nick}! </h1> <p>Your account is not active yet. Please use the link below to activate your account and start booking rooms.</p> <a href="${link}"> ACTIVATE ACCOUNT </a> </td> </tr>' WHERE name = 'Activation Code en';